if (-not (git -C $csrbt ls-tree HEAD -- tools/delivery/adr202.json)) { Write-Error "ADR202: the commit ran and this slice's manifest is not in HEAD -- refusing to report a push that did not happen"; exit 1 }
git -C $csrbt push
if ($LASTEXITCODE -ne 0) { Write-Error "ADR202: git push failed ($LASTEXITCODE) -- the commit is local and the remote does not have it"; exit 1 }
